--
-- Name: eg_wms_billing_period; Type: TABLE; Schema: health; Owner: -
--

CREATE TABLE health.eg_wms_billing_period (
    id character varying(64) NOT NULL,
    tenant_id character varying(64) NOT NULL,
    project_id character varying(256) NOT NULL,
    billing_config_id character varying(64) NOT NULL,
    period_number integer NOT NULL,
    period_start_date bigint NOT NULL,
    period_end_date bigint NOT NULL,
    billing_frequency character varying(32) NOT NULL,
    period_type character varying(32) DEFAULT 'INTERMEDIATE'::character varying NOT NULL,
    status character varying(32) DEFAULT 'PENDING'::character varying NOT NULL,
    bill_id character varying(64),
    total_amount numeric(12,2),
    beneficiary_count integer,
    register_count integer DEFAULT 0,
    muster_roll_count integer DEFAULT 0,
    created_by character varying(64) NOT NULL,
    created_time bigint NOT NULL,
    last_modified_by character varying(64),
    last_modified_time bigint,
    additional_details jsonb,
    campaign_number character varying(128) NOT NULL,
    is_deprecated boolean DEFAULT false NOT NULL,
    CONSTRAINT chk_period_dates CHECK ((period_start_date < period_end_date)),
    CONSTRAINT chk_period_number CHECK ((period_number > 0)),
    CONSTRAINT chk_period_status CHECK (((status)::text = ANY (ARRAY[('PENDING'::character varying)::text, ('PROCESSING'::character varying)::text, ('COMPLETED'::character varying)::text, ('BILLED'::character varying)::text]))),
    CONSTRAINT chk_period_type CHECK (((period_type)::text = ANY (ARRAY[('INTERMEDIATE'::character varying)::text, ('FINAL_AGGREGATE'::character varying)::text])))
);


--
-- Name: TABLE eg_wms_billing_period; Type: COMMENT; Schema: health; Owner: -
--

COMMENT ON TABLE health.eg_wms_billing_period IS 'Stores individual billing periods generated from billing configuration';


--
-- Name: COLUMN eg_wms_billing_period.id; Type: COMMENT; Schema: health; Owner: -
--

COMMENT ON COLUMN health.eg_wms_billing_period.id IS 'Unique identifier for the billing period';


--
-- Name: COLUMN eg_wms_billing_period.billing_config_id; Type: COMMENT; Schema: health; Owner: -
--

COMMENT ON COLUMN health.eg_wms_billing_period.billing_config_id IS 'References the parent billing configuration';


--
-- Name: COLUMN eg_wms_billing_period.period_number; Type: COMMENT; Schema: health; Owner: -
--

COMMENT ON COLUMN health.eg_wms_billing_period.period_number IS 'Sequential period number starting from 1';


--
-- Name: COLUMN eg_wms_billing_period.period_type; Type: COMMENT; Schema: health; Owner: -
--

COMMENT ON COLUMN health.eg_wms_billing_period.period_type IS 'Type of period: INTERMEDIATE (regular periods), FINAL_AGGREGATE (final settlement)';


--
-- Name: COLUMN eg_wms_billing_period.status; Type: COMMENT; Schema: health; Owner: -
--

COMMENT ON COLUMN health.eg_wms_billing_period.status IS 'Period status: PENDING (not started), PROCESSING (in progress), COMPLETED (done), BILLED (bill generated)';


--
-- Name: COLUMN eg_wms_billing_period.bill_id; Type: COMMENT; Schema: health; Owner: -
--

COMMENT ON COLUMN health.eg_wms_billing_period.bill_id IS 'Reference to generated bill in expense service (populated after bill generation)';


--
-- Name: COLUMN eg_wms_billing_period.register_count; Type: COMMENT; Schema: health; Owner: -
--

COMMENT ON COLUMN health.eg_wms_billing_period.register_count IS 'Number of attendance registers processed for this period';


--
-- Name: COLUMN eg_wms_billing_period.muster_roll_count; Type: COMMENT; Schema: health; Owner: -
--

COMMENT ON COLUMN health.eg_wms_billing_period.muster_roll_count IS 'Number of muster rolls generated for this period';


--
-- Name: COLUMN eg_wms_billing_period.campaign_number; Type: COMMENT; Schema: health; Owner: -
--

COMMENT ON COLUMN health.eg_wms_billing_period.campaign_number IS 'Campaign identifier this billing period belongs to';


--
-- Name: COLUMN eg_wms_billing_period.is_deprecated; Type: COMMENT; Schema: health; Owner: -
--

COMMENT ON COLUMN health.eg_wms_billing_period.is_deprecated IS 'Flag indicating if this period is deprecated due to billing config update';


