--
-- Name: record; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.record (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    record_number character varying(255) NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    previous_record_id uuid,
    application_id uuid NOT NULL,
    application_number character varying(255) NOT NULL,
    service_number character varying(255),
    tenant_id character varying(255) NOT NULL,
    module character varying(255) NOT NULL,
    business_service character varying(255) NOT NULL,
    service_code character varying(255) NOT NULL,
    workflow_status character varying(255),
    channel character varying(255),
    applicant jsonb,
    fields jsonb,
    address jsonb,
    documents jsonb,
    additional_details jsonb,
    status character varying(255) DEFAULT 'ACTIVE'::character varying,
    is_current boolean DEFAULT true,
    created_at bigint NOT NULL,
    created_by character varying(255) NOT NULL,
    updated_at bigint,
    updated_by character varying(255)
);


--
-- Name: TABLE record; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.record IS 'Record table storing versioned snapshots with merged data from multiple services';


--
-- Name: COLUMN record.id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.id IS 'UUID primary key for this record version';


--
-- Name: COLUMN record.record_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.record_number IS 'Record number - SAME across all versions (e.g., VL-REC-2025-12-29-000001)';


--
-- Name: COLUMN record.version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.version IS 'Version number (1, 2, 3, ...) - increments with each new version';


--
-- Name: COLUMN record.previous_record_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.previous_record_id IS 'Reference to previous version of this record (NULL for version 1)';


--
-- Name: COLUMN record.application_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.application_id IS 'Application that created this record version';


--
-- Name: COLUMN record.application_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.application_number IS 'Application number - DIFFERENT per version';


--
-- Name: COLUMN record.service_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.service_number IS 'Service number if applicable';


--
-- Name: COLUMN record.tenant_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.tenant_id IS 'Tenant identifier';


--
-- Name: COLUMN record.module; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.module IS 'Module name (e.g., VehicleManagement)';


--
-- Name: COLUMN record.business_service; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.business_service IS 'Business service name';


--
-- Name: COLUMN record.service_code; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.service_code IS 'Service code';


--
-- Name: COLUMN record.workflow_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.workflow_status IS 'Workflow status when record was created';


--
-- Name: COLUMN record.channel; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.channel IS 'Channel (CITIZEN, EMPLOYEE, API)';


--
-- Name: COLUMN record.applicant; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.applicant IS 'JSONB - Merged applicant data';


--
-- Name: COLUMN record.fields; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.fields IS 'JSONB - Merged fields/service_details';


--
-- Name: COLUMN record.address; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.address IS 'JSONB - Merged address data';


--
-- Name: COLUMN record.documents; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.documents IS 'JSONB - Document snapshots';


--
-- Name: COLUMN record.additional_details; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.additional_details IS 'JSONB - Additional details';


--
-- Name: COLUMN record.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.status IS 'Record status (ACTIVE, INACTIVE, CLOSED)';


--
-- Name: COLUMN record.is_current; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.is_current IS 'Boolean - true if this is the latest version, false for superseded versions';


--
-- Name: COLUMN record.created_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.created_at IS 'Record creation timestamp (epoch milliseconds)';


--
-- Name: COLUMN record.created_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.created_by IS 'User UUID who created the record';


--
-- Name: COLUMN record.updated_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.updated_at IS 'Record update timestamp (epoch milliseconds)';


--
-- Name: COLUMN record.updated_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.record.updated_by IS 'User UUID who last updated the record';


