--
-- Name: service; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.service (
    id uuid NOT NULL,
    tenant_id character varying(255) NOT NULL,
    business_service character varying(255) NOT NULL,
    module character varying(255) NOT NULL,
    service_code character varying(255) NOT NULL,
    status character varying(255),
    additional_details jsonb,
    createdby character varying(255),
    last_modifiedby character varying(255),
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    version integer DEFAULT 1
);


--
-- Name: service_code_sequence; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.service_code_sequence
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: service_code_sequence; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.service_code_sequence OWNED BY public.service.service_code;


--
-- Name: service_request_schema; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.service_request_schema (
    installed_rank integer NOT NULL,
    version character varying(50),
    description character varying(200) NOT NULL,
    type character varying(20) NOT NULL,
    script character varying(1000) NOT NULL,
    checksum integer,
    installed_by character varying(100) NOT NULL,
    installed_on timestamp without time zone DEFAULT now() NOT NULL,
    execution_time integer NOT NULL,
    success boolean NOT NULL
);


--
-- Name: service_version_config_mapping; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.service_version_config_mapping (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    service_code character varying(255) NOT NULL,
    version integer NOT NULL,
    config jsonb,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
);


--
-- Name: side_effect; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.side_effect (
    id character varying(64) NOT NULL,
    clientreferenceid character varying(64) NOT NULL,
    tenantid character varying(1000),
    taskid character varying(64),
    taskclientreferenceid character varying(64) NOT NULL,
    projectbeneficiaryid character varying(64),
    projectbeneficiaryclientreferenceid character varying(64),
    symptoms jsonb,
    createdby character varying(64),
    createdtime bigint,
    lastmodifiedby character varying(64),
    lastmodifiedtime bigint,
    clientcreatedby character varying(64),
    clientcreatedtime bigint,
    clientlastmodifiedby character varying(64),
    clientlastmodifiedtime bigint,
    rowversion bigint,
    isdeleted boolean,
    additionaldetails jsonb
);


--
-- Name: stock; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.stock (
    id character varying(64) NOT NULL,
    clientreferenceid character varying(64),
    tenantid character varying(1000),
    facilityid character varying(64),
    productvariantid character varying(64),
    quantity bigint,
    referenceid character varying(200),
    referenceidtype character varying(100),
    transactiontype character varying(100),
    transactionreason character varying(100),
    transactingpartyid character varying(64),
    transactingpartytype character varying(100),
    additionaldetails jsonb,
    createdby character varying(64),
    createdtime bigint,
    lastmodifiedby character varying(64),
    lastmodifiedtime bigint,
