-- Date-refresh: anchor seed campaign start/end dates to NOW() on first load
-- ════════════════════════════════════════════════════════════════════
DO $$ BEGIN
  UPDATE health.eg_cm_campaign_details
     SET startdate = (EXTRACT(EPOCH FROM NOW()) * 1000)::bigint,
         enddate   = (EXTRACT(EPOCH FROM NOW() + INTERVAL '90 days') * 1000)::bigint
   WHERE status IN ('drafted','created','started');
  RAISE NOTICE 'campaigns: % rows shifted', (SELECT COUNT(*) FROM health.eg_cm_campaign_details
                                              WHERE status IN ('drafted','created','started'));
EXCEPTION
  WHEN undefined_table THEN RAISE NOTICE 'health.eg_cm_campaign_details not present — skipping';
END $$;


SET session_replication_role = 'origin';

-- Workaround: the household:HCMPRE-1870 image drops householdType from its Kafka
-- payload, so persister inserts NULL. Allow NULLs on this column locally so the
-- create-household flow doesn't fail in DB. Safe — production has a fixed image.
ALTER TABLE health.household ALTER COLUMN householdtype DROP NOT NULL;

